<style>:root{--bg:#f6f8fb;--surface:#fff;--text:#122033;--muted:#637083;--border:#d8e2ee;--accent:#155ea8;--danger:#b42318;--success-bg:#e7f5ee;--success-border:#b8dec9;--success-text:#145235;font-family:"Instrument Sans",ui-sans-serif,system-ui,sans-serif}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text)}.page{min-height:100vh;padding:40px 24px}.wrap{width:min(100%,1050px);margin:auto}.header{display:flex;align-items:flex-end;justify-content:space-between;gap:16px;border-bottom:1px solid var(--border);padding-bottom:24px}.brand{margin:0 0 4px;color:var(--accent);font-size:14px;font-weight:700}h1{margin:0;font-size:clamp(28px,4vw,36px)}h2{margin:0 0 5px;font-size:19px}p{margin-top:0}.tabs{display:flex;gap:4px;border:1px solid var(--border);border-radius:8px;background:#fff;padding:4px}.tab{border-radius:6px;color:var(--muted);padding:8px 14px;font-size:14px;font-weight:700;text-decoration:none}.tab.active{background:var(--accent);color:#fff}.module-tabs{display:flex;gap:24px;margin-top:24px;border-bottom:1px solid var(--border)}.module-tab{border-bottom:3px solid transparent;color:var(--muted);padding:0 2px 12px;font-size:14px;font-weight:750;text-decoration:none}.module-tab.active{border-color:var(--accent);color:var(--accent)}.status{margin-top:24px;border:1px solid var(--success-border);border-radius:8px;background:var(--success-bg);color:var(--success-text);padding:12px 16px;font-size:14px}.error-box{margin-top:24px;border:1px solid #f0b7b3;border-radius:8px;background:#fff1f0;color:var(--danger);padding:12px 16px;font-size:14px}.layout{display:grid;grid-template-columns:430px 1fr;gap:24px;margin-top:28px;align-items:start}.panel{border:1px solid var(--border);border-radius:8px;background:#fff;padding:24px;box-shadow:0 8px 24px rgba(18,32,51,.06)}.hint,.meta{color:var(--muted);font-size:14px}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:17px 15px;margin-top:22px}.wide{grid-column:1/-1}label{display:block;font-size:14px;font-weight:700}input,select{width:100%;margin-top:8px;border:1px solid #c8d5e4;border-radius:6px;background:#fff;padding:10px 12px;font:inherit;font-size:14px}.error{margin:6px 0 0;color:var(--danger);font-size:13px}.button{display:inline-block;border:0;border-radius:6px;background:var(--accent);color:#fff;padding:11px 15px;font:inherit;font-size:14px;font-weight:700;text-decoration:none;cursor:pointer}.submit{width:100%;margin-top:21px}.submit:disabled{background:#91a4b8}.document-list{margin-top:20px;border:1px solid var(--border);border-radius:8px;overflow:hidden}.document{padding:17px;border-bottom:1px solid var(--border)}.document:last-child{border-bottom:0}.doc-head,.actions{display:flex;align-items:center;justify-content:space-between;gap:12px}.doc-name{margin:0;font-size:14px;font-weight:750}.badge{border-radius:999px;background:var(--success-bg);color:var(--success-text);padding:3px 8px;font-size:12px;font-weight:700}.actions{justify-content:flex-start;margin-top:10px}.link,.delete{border:0;background:transparent;border-radius:6px;padding:7px 8px;font:inherit;font-size:13px;font-weight:700;text-decoration:none;cursor:pointer}.link{color:var(--accent)}.delete{color:var(--danger)}.empty{padding:36px;text-align:center;color:var(--muted)}@media(max-width:900px){.layout{grid-template-columns:1fr}.header{align-items:flex-start;flex-direction:column}.tabs{width:100%;overflow:auto}.tab{flex:1;text-align:center}}@media(max-width:560px){.page{padding:24px 14px}.panel{padding:18px}.form-grid{grid-template-columns:1fr}.wide{grid-column:auto}}</style></head><body><div class="page"><main class="wrap">
