</div></div></section></main></div><script>document.addEventListener('DOMContentLoaded',()=>{const input=document.getElementById('student_lookup');const select=document.getElementById('student_id');const empty=document.getElementById('student-search-empty');if(!input||!select)return;const options=[...select.options].slice(1);const normalize=value=>value.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim();const digits=value=>value.replace(/\D/g,'');input.addEventListener('input',()=>{const term=normalize(input.value);const cpf=digits(input.value);const ranked=options.map((option,index)=>{const name=normalize(option.dataset.name||'');const optionCpf=digits(option.dataset.cpf||'');let score=term===''?0:name.startsWith(term)?1:name.includes(term)?2:(cpf!==''&&optionCpf.startsWith(cpf))?1:(cpf!==''&&optionCpf.includes(cpf))?2:99;return{option,index,score}}).sort((a,b)=>a.score-b.score||a.index-b.index);ranked.forEach(({option,score})=>{option.hidden=score===99;option.disabled=score===99;select.appendChild(option)});const matches=ranked.filter(item=>item.score!==99);empty.hidden=matches.length>0;select.value='';if(matches.length===1)select.value=matches[0].option.value});select.addEventListener('change',()=>{const selected=select.selectedOptions[0];if(selected&&selected.value)input.value=`${selected.dataset.name} — ${selected.dataset.cpf}`})});</script></body></html>
